@page "/book-appointment"
@rendermode InteractiveServer
@using sv_fe0ca2c2fba946d0bc4e6cbca03a70e4.Services
@inject AppointmentService AppointmentSvc

<PageTitle>Book Appointment</PageTitle>

<h1>Book an Appointment</h1>

<EditForm EditContext="editContext" OnValidSubmit="HandleSubmit">
    <DataAnnotationsValidator />
    <CustomValidator @ref="customValidator" />

    <fieldset>
        <legend>Patient Information</legend>

        <div class="mb-3">
            <label class="form-label">
                Patient Name
                <InputText @bind-Value="model.PatientName" class="form-control" />
                <ValidationMessage For="() => model.PatientName" />
            </label>
        </div>

        <div class="mb-3">
            <label class="form-label">
                Email
                <InputText @bind-Value="model.Email" class="form-control" />
                <ValidationMessage For="() => model.Email" />
            </label>
        </div>

        <div class="mb-3">
            <label class="form-label">
                Phone
                <InputText @bind-Value="model.Phone" class="form-control" />
                <ValidationMessage For="() => model.Phone" />
            </label>
        </div>

        <div class="mb-3">
            <label class="form-label">
                Insurance Provider
                <InputSelect @bind-Value="model.InsuranceProvider" class="form-control">
                    <option value="">-- Select --</option>
                    <option value="Aetna">Aetna</option>
                    <option value="BlueCross">BlueCross</option>
                    <option value="Cigna">Cigna</option>
                    <option value="UnitedHealth">UnitedHealth</option>
                    <option value="None">None</option>
                </InputSelect>
                <ValidationMessage For="() => model.InsuranceProvider" />
            </label>
        </div>
    </fieldset>

    @if (!showStep2)
    {
        <button type="button" class="btn btn-primary" @onclick="ProceedToStep2">
            Next: Select Appointment
        </button>
    }

    @if (showStep2)
    {
        <fieldset>
            <legend>Appointment Details</legend>

            <div class="mb-3">
                <label class="form-label">
                    Preferred Doctor
                    <InputSelect @bind-Value="model.Doctor" @bind:after="OnDoctorOrDateChanged"
                                 class="form-control">
                        <option value="">-- Select --</option>
                        @foreach (var doc in doctors)
                        {
                            <option value="@doc">@doc</option>
                        }
                    </InputSelect>
                    <ValidationMessage For="() => model.Doctor" />
                </label>
            </div>

            <div class="mb-3">
                <label class="form-label">
                    Date
                    <InputDate @bind-Value="model.AppointmentDate"
                               @bind:after="OnDoctorOrDateChanged"
                               class="form-control" />
                    <ValidationMessage For="() => model.AppointmentDate" />
                </label>
                @if (model.AppointmentDate.HasValue
                     && model.AppointmentDate.Value <= DateOnly.FromDateTime(DateTime.Today))
                {
                    <div class="validation-message">Appointment date must be in the future.</div>
                }
            </div>

            <div class="mb-3">
                <label class="form-label">
                    Time Slot
                    <InputSelect @bind-Value="model.TimeSlot" class="form-control"
                                 disabled="@(!timeSlots.Any())">
                        <option value="">-- Select --</option>
                        @foreach (var slot in timeSlots)
                        {
                            <option value="@slot">@slot</option>
                        }
                    </InputSelect>
                    <ValidationMessage For="() => model.TimeSlot" />
                </label>
                @if (!timeSlots.Any() && !string.IsNullOrEmpty(model.Doctor))
                {
                    <small class="text-muted">Select a doctor and date to see available slots.</small>
                }
            </div>

            <div class="mb-3">
                <label class="form-label">
                    Reason for Visit
                    <InputTextArea @bind-Value="model.ReasonForVisit" class="form-control"
                                   rows="3" />
                    <ValidationMessage For="() => model.ReasonForVisit" />
                </label>
                <small class="text-muted">@((model.ReasonForVisit?.Length ?? 0))/500</small>
            </div>
        </fieldset>

        <div class="mt-3">
            <button type="button" class="btn btn-secondary me-2" @onclick="BackToStep1">
                Back
            </button>
            <button type="button" class="btn btn-warning me-2" disabled="@isChecking"
                    @onclick="CheckAvailability">
                @(isChecking ? "Checking..." : "Check Availability")
            </button>
            <button type="submit" class="btn btn-success" disabled="@(!availabilityConfirmed)">
                Book Appointment
            </button>
        </div>
    }

    @if (isBooked)
    {
        <div class="alert alert-success mt-3">
            Appointment booked successfully!
        </div>
    }
</EditForm>

@code {
    private AppointmentModel model = new();
    private EditContext editContext = default!;
    private CustomValidator? customValidator;

    private bool showStep2;
    private bool isChecking;
    private bool availabilityConfirmed;
    private bool isBooked;

    private List<string> doctors = [];
    private List<string> timeSlots = [];

    // Step 1 fields for partial validation
    private static readonly string[] Step1Fields =
        [nameof(AppointmentModel.PatientName), nameof(AppointmentModel.Email),
         nameof(AppointmentModel.Phone), nameof(AppointmentModel.InsuranceProvider)];

    protected override async Task OnInitializedAsync()
    {
        editContext = new EditContext(model);
        doctors = await AppointmentSvc.GetDoctorsAsync();
    }

    private void ProceedToStep2()
    {
        // Validate only step 1 fields
        var isValid = true;
        editContext.Validate();
        foreach (var field in Step1Fields)
        {
            if (editContext.GetValidationMessages(editContext.Field(field)).Any())
            {
                isValid = false;
            }
        }

        if (isValid)
        {
            showStep2 = true;
        }
    }

    private void BackToStep1()
    {
        showStep2 = false;
        availabilityConfirmed = false;
    }

    private async Task OnDoctorOrDateChanged()
    {
        availabilityConfirmed = false;
        model.TimeSlot = null;

        if (!string.IsNullOrEmpty(model.Doctor) && model.AppointmentDate.HasValue)
        {
            timeSlots = await AppointmentSvc.GetTimeSlotsAsync(
                model.Doctor, model.AppointmentDate.Value);
        }
        else
        {
            timeSlots = [];
        }
    }

    private async Task CheckAvailability()
    {
        customValidator?.ClearErrors();
        availabilityConfirmed = false;

        // Validate step 2 fields client-side first
        editContext.Validate();
        var step2Fields = new[]
        {
            nameof(AppointmentModel.Doctor), nameof(AppointmentModel.TimeSlot),
            nameof(AppointmentModel.ReasonForVisit)
        };

        bool hasClientErrors = step2Fields
            .Any(f => editContext.GetValidationMessages(editContext.Field(f)).Any());

        if (model.AppointmentDate.HasValue
            && model.AppointmentDate.Value <= DateOnly.FromDateTime(DateTime.Today))
        {
            hasClientErrors = true;
        }

        if (!model.AppointmentDate.HasValue)
        {
            hasClientErrors = true;
        }

        if (hasClientErrors) return;

        isChecking = true;
        try
        {
            var errors = await AppointmentSvc.ValidatePatientAsync(
                model.Email ?? "",
                model.InsuranceProvider ?? "",
                model.Doctor ?? "",
                model.TimeSlot ?? "");

            if (errors.Count > 0)
            {
                customValidator!.DisplayErrors(errors);
            }
            else
            {
                availabilityConfirmed = true;
            }
        }
        finally
        {
            isChecking = false;
        }
    }

    private async Task HandleSubmit()
    {
        if (!availabilityConfirmed) return;

        // Final server-side check before booking
        var errors = await AppointmentSvc.ValidatePatientAsync(
            model.Email ?? "",
            model.InsuranceProvider ?? "",
            model.Doctor ?? "",
            model.TimeSlot ?? "");

        if (errors.Count > 0)
        {
            customValidator!.DisplayErrors(errors);
            availabilityConfirmed = false;
            return;
        }

        isBooked = true;
    }
}

